/**
 * Get today's clinical pearl. Pure function of the date - same pearl
 * is shown to every visitor on the same day, and rotates annually.
 */
export function getDailyPearl(date: Date = new Date()): string {
  const startOfYear = new Date(date.getFullYear(), 0, 0);
  const diff = date.getTime() - startOfYear.getTime();
  const oneDay = 1000 * 60 * 60 * 24;
  const dayOfYear = Math.floor(diff / oneDay);
  return CLINICAL_PEARLS[dayOfYear % CLINICAL_PEARLS.length];
}

/** Tomorrow's pearl - useful for "tomorrow's preview" teasers. */
export function getTomorrowPearl(date: Date = new Date()): string {
  const tomorrow = new Date(date);
  tomorrow.setDate(date.getDate() + 1);
  return getDailyPearl(tomorrow);
}

/** Total pearl count (for marketing / UI display). */
export const PEARL_COUNT = CLINICAL_PEARLS.length;
